<script lang="ts">
 import {untrack} from 'svelte';import {encodings,encode,decode,garble,recover,parseHex,type Charset} from './logic';import Result from '../../components/Result.svelte';import {download} from '../../browser-files';import type {ToolState} from '../../types';
 let {state=$bindable()}: {state:ToolState} = $props();untrack(()=>{state.text??='';state.from??='UTF8';state.wrong??='SJIS';state.hex??='';state.output??='';state.error??='';});
 function run(mode:string){try{if(mode==='encode'){const b=encode(state.text,state.from);state.hex=[...b].map(v=>v.toString(16).padStart(2,'0')).join(' ');state.output=state.hex;}else if(mode==='decode')state.output=decode(parseHex(state.hex),state.from);else if(mode==='garble')state.output=garble(state.text,state.from,state.wrong);else{const candidates=recover(state.text);state.output=candidates.length?candidates.map(c=>`[${c.route}]\n${c.text}`).join('\n\n'):'完全に往復できる復元候補はありません。置換文字 � や欠落バイトを含む文字列は復元できない場合があります。';}state.error='';}catch(e){state.error=(e as Error).message;state.output='';}}
 async function file(event:Event){const input=event.currentTarget as HTMLInputElement,f=input.files?.[0];if(!f)return;try{if(f.size>100000)throw new Error('100KB以下のファイルを選択してください。');const bytes=new Uint8Array(await f.arrayBuffer());state.hex=[...bytes].map(b=>b.toString(16).padStart(2,'0')).join(' ');state.output=decode(bytes,state.from);state.error='';}catch(e){state.error=(e as Error).message;}finally{input.value='';}}
 function save(){try{download(new Blob([new Uint8Array(encode(state.text,state.from))],{type:'application/octet-stream'}),`toolbox-${state.from}.txt`);state.error='';}catch(e){state.error=(e as Error).message;}}
</script>
<div class="form-grid"><label>本来の文字コード / バイト変換用<select bind:value={state.from}>{#each encodings as e}<option>{e}</option>{/each}</select></label><label>誤って読む文字コード<select bind:value={state.wrong}>{#each encodings as e}<option>{e}</option>{/each}</select></label></div>
<label>テキスト（生成時は正常文、復元時は文字化け文）<textarea rows="5" maxlength="20000" bind:value={state.text} placeholder="例: 日本"></textarea></label>
<div class="action-row"><button class="primary" onclick={()=>run('garble')}>文字化けを生成</button><button onclick={()=>run('recover')}>復元候補を探す</button><button onclick={()=>run('encode')}>バイト列を表示</button><button onclick={save}>文字コード指定で保存</button></div>
<label>16進バイト列<textarea rows="3" maxlength="300000" bind:value={state.hex} placeholder="e6 97 a5 e6 9c ac"></textarea></label>
<div class="action-row"><button onclick={()=>run('decode')}>バイト列を解読</button><button onclick={()=>{state.text='';state.hex='';state.output='';state.error='';}}>クリア</button></div><label class="file-line">ファイルから解読（100KBまで）<input type="file" onchange={file}/></label>
{#if state.error}<p role="alert" class="error">{state.error}</p>{/if}<Result text={state.output}/><p class="tool-note">UTF8 / SJIS（Windows-31J互換）/ EUCJP / JIS / UTF16LE。変換できない文字はエラー。文字化け生成では欠落を示す � が発生し得ます。復元は可逆な候補だけを提示し、正解を保証しません。テキスト20,000文字・バイト列100KBまで。</p>
